#!/usr/bin/env python3
"""Writes rtl/itch_pkg.sv: the counter index list comes from model/ref.py COUNTERS (one list for the model, the RTL and the docs).

    python3 designs/b110_itch_ouch/scripts/gen_pkg.py [--check]
"""
from __future__ import annotations

import sys
from pathlib import Path

D = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(D.parents[1]))
from designs.b110_itch_ouch.model.ref import COUNTERS  # noqa: E402


def render() -> str:
    lines = [
        "// itch_pkg.sv: counter indices of the 32-bit counter bus (generated by scripts/gen_pkg.py from model/ref.py COUNTERS; do not edit).",
        "// Counter k of the bus `cnt` is cnt[32*k +: 32]. Brief 110.",
        "package itch_pkg;",
        f"    localparam int NC = {len(COUNTERS)};",
    ]
    for i, n in enumerate(COUNTERS):
        lines.append(f"    localparam int C_{n.upper()} = {i};")
    lines.append("endpackage")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    out = D / "rtl" / "itch_pkg.sv"
    if "--check" in sys.argv:
        sys.exit(0 if out.read_text() == render() else 1)
    out.write_text(render())
